// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [2473451973, 3110666693, 637231557, 524624325, 3377656261, 2637322693, 972675525, 3935168965, 1830195653, 2783066565, 3492499909, 357163461, 2292865477, 3803922885, 2165946821, 809685445];
const blocks = ["NFD U+050000-U+050FFF", "NFD U+051000-U+051FFF", "NFD U+052000-U+052FFF", "NFD U+053000-U+053FFF", "NFD U+054000-U+054FFF", "NFD U+055000-U+055FFF", "NFD U+056000-U+056FFF", "NFD U+057000-U+057FFF", "NFD U+058000-U+058FFF", "NFD U+059000-U+059FFF", "NFD U+05A000-U+05AFFF", "NFD U+05B000-U+05BFFF", "NFD U+05C000-U+05CFFF", "NFD U+05D000-U+05DFFF", "NFD U+05E000-U+05EFFF", "NFD U+05F000-U+05FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 327680 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
